"use client"

import { cn } from "@/lib/utils"

export interface ChartPoint {
  label: string
  value: number
}

export interface AnswerChartProps {
  data: ChartPoint[]
  type?: "bar" | "line"
  caption?: string
  empty?: string
  className?: string
}

export function AnswerChart({ data, type = "bar", caption, empty = "Nothing to chart", className }: AnswerChartProps) {
  const label = caption ?? data.map((point) => `${point.label} ${point.value}`).join(", ")

  return (
    <figure className={cn("w-full shrink-0", className)}>
      {data.length === 0 ? (
        <p className="rounded-2xl border border-border px-4 py-6 text-center text-sm text-muted-foreground">{empty}</p>
      ) : type === "line" ? (
        <LineChart data={data} label={label} />
      ) : (
        <BarChart data={data} label={label} />
      )}
      {caption && <figcaption className="mt-2 text-xs text-muted-foreground">{caption}</figcaption>}
    </figure>
  )
}

function BarChart({ data, label }: { data: ChartPoint[]; label: string }) {
  const max = Math.max(...data.map((point) => point.value), 1)
  return (
    <div className="flex h-44 items-end gap-3" role="img" aria-label={label}>
      {data.map((point) => (
        <div key={point.label} className="flex h-full min-w-0 flex-1 flex-col items-center justify-end gap-1.5">
          <span className="text-xs tabular-nums text-muted-foreground">{point.value}</span>
          <div className="flex h-28 w-full items-end overflow-hidden rounded-md bg-muted">
            <div className="w-full rounded-md bg-primary" style={{ height: `${(point.value / max) * 100}%` }} />
          </div>
          <span className="w-full truncate text-center text-xs text-muted-foreground">{point.label}</span>
        </div>
      ))}
    </div>
  )
}

function LineChart({ data, label }: { data: ChartPoint[]; label: string }) {
  const width = 320
  const height = 140
  const pad = 12
  const max = Math.max(...data.map((point) => point.value), 1)
  const span = Math.max(data.length - 1, 1)
  const coords = data.map((point, index) => {
    const x = pad + ((width - pad * 2) * index) / span
    const y = height - pad - ((height - pad * 2) * point.value) / max
    return `${x},${y}`
  })

  return (
    <div role="img" aria-label={label}>
      <svg viewBox={`0 0 ${width} ${height}`} className="h-36 w-full text-primary">
        <polyline
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinejoin="round"
          strokeLinecap="round"
          points={coords.join(" ")}
        />
        {coords.map((pair, index) => {
          const [x, y] = pair.split(",")
          return <circle key={data[index].label} cx={x} cy={y} r="3" fill="currentColor" />
        })}
      </svg>
      <div className="mt-1 flex gap-3">
        {data.map((point) => (
          <span key={point.label} className="min-w-0 flex-1 truncate text-center text-xs text-muted-foreground">
            {point.label}
          </span>
        ))}
      </div>
    </div>
  )
}
